if(NS.UI){const setPrev=NS.UI.prototype.setWorld,headPrev=NS.UI.prototype.renderHeader,tilePrev=NS.UI.prototype.renderTile,contentPrev=NS.UI.prototype.renderVillageContent,codexPrev=NS.UI.prototype.renderCodex;NS.UI.prototype.setWorld=function(w){return setPrev.call(this,attachE1(w));};NS.UI.prototype.renderHeader=function(){const r=headPrev.call(this);document.title='Village Observer V0.33E1';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.33E1</strong>';const st=this.q?.('runtimeStatus');if(st){const fs=(this.world.activeVillages||[]).flatMap(v=>formations(v,this.world).filter(f=>formationPeople(v,f).length)),cmd=fs.filter(f=>{const v=(this.world.villages||[]).find(x=>Number(x.id)===Number(f.nationId));return v&&commanderPerson(v,f);}).length;st.textContent=`✓ V0.33E1 시대압축·Formation Command · Tech ${NS.TECH_ORDER.length}/${TECH_COST_TOTAL_E1}K · Knowledge ×1.00 · Commander ${cmd}/${fs.length} · War UI single writer`;}return r;};NS.UI.prototype.renderTile=function(){const r=tilePrev.call(this);renderTileIdentity(this);renderTileCommander(this);return r;};NS.UI.prototype.renderVillageContent=function(){const r=contentPrev.call(this);renderCommanderPanel(this);return r;};NS.UI.prototype.renderCodex=function(){const r=codexPrev.call(this),el=this.q?.('codexContent');if(el&&!el.querySelector('.v33e1-note')){const note=document.createElement('div');note.className='codex-note v33e1-note';note.innerHTML='<strong>V0.33E1 시대 진행·Formation Command V1</strong><br>기술 트리를 40개에서 32개로 통폐합하되 남는 기술의 개별 비용과 Knowledge 생산 공식은 변경하지 않습니다. 각 야전 Formation은 실제 현역 성인 Person 중 Command Score 45 이상 후보가 있을 때 지휘관을 둘 수 있습니다. 지휘관 보너스는 최대 전투 +8%, 패전 사기손실 완화 최대 15%, regroup 단축 최대 10%로 제한되며 실제 부상·사망 시 효과를 잃습니다. 1~4인 소규모 Formation의 연속 사상 변동은 완화하지만 모든 사상자는 계속 실제 Person에 적용됩니다.';(el.querySelector('[data-page="war"]')||el).insertAdjacentElement('afterbegin',note);}return r;};}
